import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ModernDashboard = ({ token, setToken }) => {
  const [stats, setStats] = useState({ total: 0, anomalies: 0, normal: 0 });
  const [entries, setEntries] = useState([]);
  const [totalAmount, setTotalAmount] = useState(0);
  const [monthlyGrowth, setMonthlyGrowth] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (token) {
      fetchData();
    }
  }, [token]);

  const fetchData = async () => {
    try {
      const [ledgerRes, analyticsRes] = await Promise.all([
        axios.get('http://localhost:5000/api/ledger', {
          headers: { Authorization: `Bearer ${token}` }
        }),
        axios.get('http://localhost:5000/api/analytics', {
          headers: { Authorization: `Bearer ${token}` }
        })
      ]);

      const ledgerData = ledgerRes.data;
      const analyticsData = analyticsRes.data;

      setStats({
        total: ledgerData.total_count,
        anomalies: ledgerData.anomaly_count,
        normal: ledgerData.total_count - ledgerData.anomaly_count
      });

      setEntries(ledgerData.entries.slice(0, 5));

      const total = ledgerData.entries.reduce((sum, entry) => sum + parseFloat(entry.amount), 0);
      setTotalAmount(total);

      // Calculate monthly growth (mock calculation)
      setMonthlyGrowth(12.5);

      setLoading(false);
    } catch (error) {
      console.error('Error fetching data:', error);
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR'
    }).format(amount);
  };

  const handleLogout = () => {
    setToken(null);
    localStorage.removeItem('token');
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#120a1a] flex items-center justify-center">
        <div className="text-white text-xl">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#120a1a] text-slate-100 flex overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 border-r border-[#2d2438] flex flex-col h-screen shrink-0 bg-[#120a1a]">
        <div className="p-6">
          <div className="flex items-center gap-2 text-[#8c2bee]">
            <span className="text-3xl font-bold">⚡</span>
            <h1 className="text-xl font-bold tracking-tight text-white">FinanceGuard</h1>
          </div>
          <p className="text-xs text-slate-400 mt-1">Anomaly Detection System</p>
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto">
          <div className="flex items-center gap-3 px-3 py-2 rounded-lg bg-[#8c2bee]/10 text-[#8c2bee]">
            <span>📊</span>
            <p className="text-sm font-medium">Dashboard</p>
          </div>
          <div className="flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-[#1d1429] transition-colors cursor-pointer rounded-lg">
            <span>💰</span>
            <p className="text-sm font-medium">Transactions</p>
          </div>
          <div className="flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-[#1d1429] transition-colors cursor-pointer rounded-lg">
            <span>📈</span>
            <p className="text-sm font-medium">Analytics</p>
          </div>
          <div className="flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-[#1d1429] transition-colors cursor-pointer rounded-lg">
            <span>⚠️</span>
            <p className="text-sm font-medium">Anomalies</p>
          </div>
          <div className="flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-[#1d1429] transition-colors cursor-pointer rounded-lg">
            <span>📄</span>
            <p className="text-sm font-medium">Reports</p>
          </div>

          <div className="mt-8 mb-2 px-3 text-[10px] uppercase tracking-wider text-slate-500 font-bold">Preferences</div>
          <div className="flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-[#1d1429] transition-colors cursor-pointer rounded-lg">
            <span>⚙️</span>
            <p className="text-sm font-medium">Settings</p>
          </div>
          <div className="flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-[#1d1429] transition-colors cursor-pointer rounded-lg">
            <span>❓</span>
            <p className="text-sm font-medium">Help & Support</p>
          </div>
        </nav>

        <div className="p-4 border-t border-[#2d2438]">
          <div onClick={handleLogout} className="flex items-center gap-3 px-3 py-2 text-red-400 hover:bg-red-400/10 transition-colors cursor-pointer rounded-lg">
            <span>🚪</span>
            <p className="text-sm font-medium">Log Out</p>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-[#120a1a]">
        {/* Header */}
        <header className="h-16 border-b border-[#2d2438] flex items-center justify-between px-8 shrink-0 bg-[#120a1a]">
          <div className="flex items-center gap-4">
            <h2 className="text-lg font-bold text-white">Good Morning, Admin!</h2>
            <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-[#8c2bee]/20 text-[#8c2bee] uppercase">System Manager</span>
          </div>
          <div className="flex items-center gap-4">
            <button className="relative p-2 text-slate-500 hover:text-[#8c2bee] transition-colors">
              <span>💬</span>
              <span className="absolute top-2 right-2 w-2 h-2 bg-[#8c2bee] rounded-full border-2 border-[#120a1a]"></span>
            </button>
            <button className="p-2 text-slate-500 hover:text-[#8c2bee] transition-colors">
              <span>🔔</span>
            </button>
            <div className="h-8 w-8 rounded-full bg-[#1d1429] border border-[#2d2438] flex items-center justify-center text-[#8c2bee] font-bold cursor-pointer">
              A
            </div>
          </div>
        </header>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-8">
          <div className="grid grid-cols-12 gap-6">
            {/* Left Column */}
            <div className="col-span-12 lg:col-span-8 flex flex-col gap-6">
              {/* Performance Card */}
              <div className="bg-[#1d1429]/60 backdrop-blur-xl border border-[#8c2bee]/10 rounded-xl p-6">
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <p className="text-slate-400 text-sm font-medium">Total Transaction Value</p>
                    <h3 className="text-3xl font-bold text-white mt-1">{formatCurrency(totalAmount)}</h3>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-emerald-400 text-sm font-bold flex items-center">
                        ↗ +{monthlyGrowth}%
                      </span>
                      <span className="text-slate-500 text-xs">This Month vs Last Month</span>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button className="px-3 py-1 text-xs rounded-lg bg-[#1d1429] border border-[#2d2438] text-slate-300">Daily</button>
                    <button className="px-3 py-1 text-xs rounded-lg bg-[#8c2bee] text-white font-medium">Monthly</button>
                  </div>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-3 gap-4 mt-6">
                  <div className="bg-[#1d1429] border border-[#2d2438] rounded-lg p-4">
                    <p className="text-slate-400 text-xs font-medium mb-1">Total Entries</p>
                    <p className="text-2xl font-bold text-white">{stats.total}</p>
                  </div>
                  <div className="bg-emerald-400/10 border border-emerald-400/20 rounded-lg p-4">
                    <p className="text-emerald-400 text-xs font-medium mb-1">Normal</p>
                    <p className="text-2xl font-bold text-emerald-400">{stats.normal}</p>
                  </div>
                  <div className="bg-red-400/10 border border-red-400/20 rounded-lg p-4">
                    <p className="text-red-400 text-xs font-medium mb-1">Anomalies</p>
                    <p className="text-2xl font-bold text-red-400">{stats.anomalies}</p>
                  </div>
                </div>
              </div>

              {/* Transaction List */}
              <div className="bg-[#1d1429]/60 backdrop-blur-xl border border-[#8c2bee]/10 rounded-xl overflow-hidden">
                <div className="p-6 border-b border-[#2d2438] flex justify-between items-center">
                  <h4 className="font-bold text-white">Recent Transactions</h4>
                  <button className="text-[#8c2bee] text-sm font-medium hover:underline">View All</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-[#1d1429]/50">
                      <tr>
                        <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Date</th>
                        <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Description</th>
                        <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Amount</th>
                        <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#2d2438]">
                      {entries.map((entry) => (
                        <tr key={entry.id} className="hover:bg-[#8c2bee]/5 transition-colors">
                          <td className="px-6 py-4 text-sm text-slate-400 font-medium">{entry.date}</td>
                          <td className="px-6 py-4 text-sm font-medium text-slate-200">{entry.description}</td>
                          <td className="px-6 py-4 text-sm text-slate-200 font-bold">{formatCurrency(entry.amount)}</td>
                          <td className="px-6 py-4">
                            {entry.is_anomaly ? (
                              <span className="px-2 py-1 rounded text-[10px] font-bold bg-red-400/10 text-red-400 uppercase">Anomaly</span>
                            ) : (
                              <span className="px-2 py-1 rounded text-[10px] font-bold bg-emerald-400/10 text-emerald-400 uppercase">Normal</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>

            {/* Right Column */}
            <div className="col-span-12 lg:col-span-4 flex flex-col gap-6">
              {/* Detection Status */}
              <div className="bg-[#1d1429]/60 backdrop-blur-xl border border-[#8c2bee]/10 rounded-xl p-6">
                <div className="flex justify-between items-center mb-4">
                  <h4 className="font-bold text-white">Detection Status</h4>
                  <span className="text-[#8c2bee] font-bold">{((stats.normal / stats.total) * 100).toFixed(0)}%</span>
                </div>
                <div className="w-full h-3 bg-slate-800 rounded-full overflow-hidden mb-4">
                  <div className="h-full bg-[#8c2bee] rounded-full shadow-[0_0_15px_rgba(140,43,238,0.5)]" style={{width: `${(stats.normal / stats.total) * 100}%`}}></div>
                </div>
                <div className="space-y-4">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded bg-[#8c2bee]/20 flex items-center justify-center">
                      <span className="text-[#8c2bee] text-sm">🤖</span>
                    </div>
                    <div>
                      <p className="text-xs font-bold text-slate-200">ML Model Active</p>
                      <p className="text-[10px] text-slate-500">Isolation Forest Algorithm</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Anomaly Alert */}
              <div className="bg-gradient-to-br from-[#8c2bee] to-purple-800 rounded-xl p-6 text-white relative overflow-hidden">
                <div className="relative z-10">
                  <h4 className="text-xl font-extrabold mb-1">⚠️ Alert System</h4>
                  <p className="text-purple-100/70 text-sm mb-4">Real-time anomaly detection with email notifications.</p>
                  <div className="flex items-baseline gap-1 mb-6">
                    <span className="text-3xl font-bold">{stats.anomalies}</span>
                    <span className="text-xs opacity-70">detected</span>
                  </div>
                  <button className="w-full py-3 bg-white text-[#8c2bee] font-bold rounded-lg hover:bg-slate-100 transition-all shadow-lg">
                    View Anomalies
                  </button>
                </div>
              </div>

              {/* System Info */}
              <div className="bg-[#1d1429]/60 backdrop-blur-xl border border-[#8c2bee]/10 rounded-xl p-6">
                <h4 className="font-bold text-white mb-4">System Info</h4>
                <div className="space-y-3">
                  <div className="flex justify-between items-center p-3 rounded-lg bg-[#1d1429] border border-[#2d2438]">
                    <span className="text-sm font-medium text-slate-300">Database</span>
